import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Tradeboard API Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"api-documentation/v1/README.md","filePath":"api-documentation/v1/README.md"}'),r={name:"api-documentation/v1/README.md"};function s(i,t,c,n,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="tradeboard-api-documentation" tabindex="-1">Tradeboard API Documentation <a class="header-anchor" href="#tradeboard-api-documentation" aria-label="Permalink to &quot;Tradeboard API Documentation&quot;">​</a></h1><p>This directory documents the registered Tradeboard v1 REST API and the separate WebSocket protocol. The source of truth for REST registration is <code>restx_api/__init__.py</code>; request validation is defined in <code>restx_api/schemas.py</code>, <code>restx_api/data_schemas.py</code>, <code>restx_api/account_schema.py</code>, and <code>restx_api/strategy_schema.py</code>.</p><h2 id="base-urls" tabindex="-1">Base URLs <a class="header-anchor" href="#base-urls" aria-label="Permalink to &quot;Base URLs&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REST API:  http://127.0.0.1:5000/api/v1</span></span>
<span class="line"><span>WebSocket: ws://127.0.0.1:8765</span></span></code></pre></div><p>Replace the local host with the configured HTTPS/WSS domain in a remote deployment.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Most POST endpoints accept the Tradeboard API key as <code>apikey</code> in a JSON object. GET endpoints accept it as the <code>apikey</code> query parameter. Telegram and WhatsApp management endpoints may also accept <code>X-API-KEY</code>; the Telegram webhook authenticates with <code>X-Telegram-Bot-Api-Secret-Token</code> instead of an Tradeboard key.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apikey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;your_app_apikey&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Never put broker credentials or broker access tokens in these requests. The Tradeboard API key resolves the active broker session server-side.</p><h2 id="strict-request-validation" tabindex="-1">Strict Request Validation <a class="header-anchor" href="#strict-request-validation" aria-label="Permalink to &quot;Strict Request Validation&quot;">​</a></h2><p>POST bodies are deserialized by marshmallow schemas that do not set <code>Meta.unknown</code>, so marshmallow&#39;s default of <code>RAISE</code> applies: a field the schema does not declare makes the whole request fail with HTTP 400, even when every other field is valid. Treat each endpoint page&#39;s request-body table as the exact allowed field set rather than a summary. The GTT place and modify schemas set <code>unknown = EXCLUDE</code> and silently drop extras instead; chart preferences sets <code>unknown = INCLUDE</code> because arbitrary preference keys are the point of that resource.</p><p>GET resources (<code>/instruments</code>, <code>/ticker/&lt;symbol&gt;</code>, <code>/chart</code>, <code>/telegram/*</code>) read query parameters directly and ignore unrecognized ones.</p><h2 id="registered-rest-inventory" tabindex="-1">Registered REST Inventory <a class="header-anchor" href="#registered-rest-inventory" aria-label="Permalink to &quot;Registered REST Inventory&quot;">​</a></h2><p>The current v1 surface contains <strong>71 method/path pairs</strong>. A resource with both GET and POST counts as two endpoints.</p><h3 id="order-management" tabindex="-1">Order Management <a class="header-anchor" href="#order-management" aria-label="Permalink to &quot;Order Management&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>POST</td><td><code>/placeorder</code></td><td><a href="./orders-api/placeorder.html">Place order</a></td></tr><tr><td>POST</td><td><code>/placesmartorder</code></td><td><a href="./orders-api/placesmartorder.html">Place smart order</a></td></tr><tr><td>POST</td><td><code>/optionsorder</code></td><td><a href="./orders-api/optionsorder.html">Options order</a></td></tr><tr><td>POST</td><td><code>/optionsmultiorder</code></td><td><a href="./orders-api/optionsmultiorder.html">Options multi-order</a></td></tr><tr><td>POST</td><td><code>/basketorder</code></td><td><a href="./orders-api/basketorder.html">Basket order</a></td></tr><tr><td>POST</td><td><code>/splitorder</code></td><td><a href="./orders-api/splitorder.html">Split order</a></td></tr><tr><td>POST</td><td><code>/modifyorder</code></td><td><a href="./orders-api/modifyorder.html">Modify order</a></td></tr><tr><td>POST</td><td><code>/cancelorder</code></td><td><a href="./orders-api/cancelorder.html">Cancel order</a></td></tr><tr><td>POST</td><td><code>/cancelallorder</code></td><td><a href="./orders-api/cancelallorder.html">Cancel all orders</a></td></tr><tr><td>POST</td><td><code>/closeposition</code></td><td><a href="./orders-api/closeposition.html">Close positions</a></td></tr><tr><td>POST</td><td><code>/placegttorder</code></td><td><a href="./orders-api/placegttorder.html">Place GTT</a></td></tr><tr><td>POST</td><td><code>/modifygttorder</code></td><td><a href="./orders-api/modifygttorder.html">Modify GTT</a></td></tr><tr><td>POST</td><td><code>/cancelgttorder</code></td><td><a href="./orders-api/cancelgttorder.html">Cancel GTT</a></td></tr><tr><td>POST</td><td><code>/gttorderbook</code></td><td><a href="./orders-api/gttorderbook.html">GTT order book</a></td></tr></tbody></table><h3 id="order-and-account-information" tabindex="-1">Order And Account Information <a class="header-anchor" href="#order-and-account-information" aria-label="Permalink to &quot;Order And Account Information&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>POST</td><td><code>/orderstatus</code></td><td><a href="./orders-api/orderstatus.html">Order status</a></td></tr><tr><td>POST</td><td><code>/openposition</code></td><td><a href="./orders-api/openposition.html">Open position</a></td></tr><tr><td>POST</td><td><code>/funds</code></td><td><a href="./accounts-api/funds.html">Funds</a></td></tr><tr><td>POST</td><td><code>/margin</code></td><td><a href="./accounts-api/margin.html">Margin</a></td></tr><tr><td>POST</td><td><code>/orderbook</code></td><td><a href="./accounts-api/orderbook.html">Order book</a></td></tr><tr><td>POST</td><td><code>/tradebook</code></td><td><a href="./accounts-api/tradebook.html">Trade book</a></td></tr><tr><td>POST</td><td><code>/positionbook</code></td><td><a href="./accounts-api/positionbook.html">Position book</a></td></tr><tr><td>POST</td><td><code>/holdings</code></td><td><a href="./accounts-api/holdings.html">Holdings</a></td></tr></tbody></table><h3 id="market-data-and-symbols" tabindex="-1">Market Data And Symbols <a class="header-anchor" href="#market-data-and-symbols" aria-label="Permalink to &quot;Market Data And Symbols&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>POST</td><td><code>/quotes</code></td><td><a href="./data-api/quotes.html">Quote</a></td></tr><tr><td>POST</td><td><code>/multiquotes</code></td><td><a href="./data-api/multiquotes.html">Multiple quotes</a></td></tr><tr><td>POST</td><td><code>/depth</code></td><td><a href="./data-api/depth.html">Market depth</a></td></tr><tr><td>POST</td><td><code>/history</code></td><td><a href="./data-api/history.html">Historical candles</a></td></tr><tr><td>POST</td><td><code>/intervals</code></td><td><a href="./data-api/intervals.html">Supported intervals</a></td></tr><tr><td>GET</td><td><code>/ticker/&lt;string:symbol&gt;</code></td><td><a href="./data-api/ticker.html">Ticker-compatible history</a></td></tr><tr><td>POST</td><td><code>/symbol</code></td><td><a href="./data-api/symbol.html">Symbol information</a></td></tr><tr><td>POST</td><td><code>/search</code></td><td><a href="./data-api/search.html">Symbol search</a></td></tr><tr><td>POST</td><td><code>/expiry</code></td><td><a href="./data-api/expiry.html">Expiry dates</a></td></tr><tr><td>GET</td><td><code>/instruments</code></td><td><a href="./data-api/instruments.html">Instrument master</a></td></tr></tbody></table><h3 id="options-analytics" tabindex="-1">Options Analytics <a class="header-anchor" href="#options-analytics" aria-label="Permalink to &quot;Options Analytics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>POST</td><td><code>/optionsymbol</code></td><td><a href="./data-api/optionsymbol.html">Resolve option symbol</a></td></tr><tr><td>POST</td><td><code>/optionchain</code></td><td><a href="./data-api/option-chain.html">Option chain</a></td></tr><tr><td>POST</td><td><code>/syntheticfuture</code></td><td><a href="./data-api/syntheticfuture.html">Synthetic future</a></td></tr><tr><td>POST</td><td><code>/optiongreeks</code></td><td><a href="./data-api/optiongreeks.html">Option Greeks</a></td></tr><tr><td>POST</td><td><code>/multioptiongreeks</code></td><td><a href="./data-api/multioptiongreeks.html">Batch option Greeks</a></td></tr></tbody></table><h3 id="calendar-analyzer-and-preferences" tabindex="-1">Calendar, Analyzer, And Preferences <a class="header-anchor" href="#calendar-analyzer-and-preferences" aria-label="Permalink to &quot;Calendar, Analyzer, And Preferences&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>POST</td><td><code>/market/holidays</code></td><td><a href="./utilities-api/holidays.html">Market holidays</a></td></tr><tr><td>POST</td><td><code>/market/timings</code></td><td><a href="./utilities-api/timings.html">Market timings</a></td></tr><tr><td>POST</td><td><code>/analyzer</code></td><td><a href="./accounts-api/analyzer-status.html">Analyzer status</a></td></tr><tr><td>POST</td><td><code>/analyzer/toggle</code></td><td><a href="./accounts-api/analyzer-toggle.html">Toggle analyzer mode</a></td></tr><tr><td>POST</td><td><code>/pnl/symbols</code></td><td><a href="./accounts-api/pnl-symbols.html">Sandbox P&amp;L by symbol</a></td></tr><tr><td>GET</td><td><code>/chart</code></td><td><a href="./accounts-api/chart-preferences.html">Read chart preferences</a></td></tr><tr><td>POST</td><td><code>/chart</code></td><td><a href="./accounts-api/chart-preferences.html">Update chart preferences</a></td></tr><tr><td>POST</td><td><code>/ping</code></td><td><a href="./accounts-api/ping.html">Authenticated ping</a></td></tr></tbody></table><p>There is no public <code>/api/v1/checkholiday</code> endpoint. Use <code>/market/timings</code> for a date; its response identifies holiday/closed sessions through the returned market schedule.</p><h3 id="portfolio-analytics" tabindex="-1">Portfolio Analytics <a class="header-anchor" href="#portfolio-analytics" aria-label="Permalink to &quot;Portfolio Analytics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>GET</td><td><code>/portfolio/benchmarks</code></td><td><a href="./portfolio.html">Portfolio API</a></td></tr><tr><td>POST</td><td><code>/portfolio/backtest</code></td><td><a href="./portfolio.html">Portfolio API</a></td></tr><tr><td>POST</td><td><code>/portfolio/tearsheet</code></td><td><a href="./portfolio.html">Portfolio API</a></td></tr><tr><td>POST</td><td><code>/portfolio/holdings</code></td><td><a href="./portfolio.html">Portfolio API</a></td></tr></tbody></table><p>Portfolio endpoints are authenticated and read-only. The holdings resource reads the active broker account, but none of these resources places, modifies, or cancels an order.</p><h3 id="strategy-rms-engine" tabindex="-1">Strategy RMS Engine <a class="header-anchor" href="#strategy-rms-engine" aria-label="Permalink to &quot;Strategy RMS Engine&quot;">​</a></h3><p>The Strategy RMS Engine lifecycle and audit surface is under <code>/strategy</code>. It contains nine authenticated RESTX routes; strategy creation, editing, live enablement, token rotation, and deletion remain browser/session operations.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>POST</td><td><code>/strategy/list</code></td><td><a href="./strategy-rms-api/list.html">List strategies</a></td></tr><tr><td>POST</td><td><code>/strategy/status</code></td><td><a href="./strategy-rms-api/status.html">Strategy status</a></td></tr><tr><td>POST</td><td><code>/strategy/start</code></td><td><a href="./strategy-rms-api/start.html">Start run</a></td></tr><tr><td>POST</td><td><code>/strategy/stop</code></td><td><a href="./strategy-rms-api/stop.html">Stop run</a></td></tr><tr><td>POST</td><td><code>/strategy/close_all</code></td><td><a href="./strategy-rms-api/close-all.html">Close all legs</a></td></tr><tr><td>POST</td><td><code>/strategy/close_leg</code></td><td><a href="./strategy-rms-api/close-leg.html">Close one leg</a></td></tr><tr><td>POST</td><td><code>/strategy/runs</code></td><td><a href="./strategy-rms-api/runs.html">Run history</a></td></tr><tr><td>POST</td><td><code>/strategy/orders</code></td><td><a href="./strategy-rms-api/orders.html">Order history</a></td></tr><tr><td>POST</td><td><code>/strategy/events</code></td><td><a href="./strategy-rms-api/events.html">Risk event audit trail</a></td></tr></tbody></table><p>The public alert endpoint is <code>POST /strategy/webhook/&lt;token&gt;</code>. It is deliberately outside <code>/api/v1</code>, uses the URL token rather than <code>apikey</code>, and is documented separately in <a href="./strategy-rms-api/webhook.html">Public Strategy Webhook</a>. It is not included in the 71 RESTX route count above.</p><h3 id="sip-analytics" tabindex="-1">SIP Analytics <a class="header-anchor" href="#sip-analytics" aria-label="Permalink to &quot;SIP Analytics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>GET</td><td><code>/sip/frequencies</code></td><td><a href="./utilities-api/sip-backtest.html">SIP Backtest</a></td></tr><tr><td>POST</td><td><code>/sip/backtest</code></td><td><a href="./utilities-api/sip-backtest.html">SIP Backtest</a></td></tr></tbody></table><p><code>/sip/backtest</code> validates against <code>SipBacktestSchema</code> and requires a valid API key; <code>source: &quot;api&quot;</code> additionally requires a broker session. <code>/sip/frequencies</code> returns the frequency list the engine supports and is the one v1 resource that does not verify the API key. Both use <code>SIP_API_RATE_LIMIT</code>, default <code>10 per minute</code>.</p><h3 id="messaging" tabindex="-1">Messaging <a class="header-anchor" href="#messaging" aria-label="Permalink to &quot;Messaging&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Documentation</th></tr></thead><tbody><tr><td>GET, POST</td><td><code>/telegram/config</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>POST</td><td><code>/telegram/start</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>POST</td><td><code>/telegram/stop</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>POST</td><td><code>/telegram/webhook</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>GET</td><td><code>/telegram/users</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>POST</td><td><code>/telegram/broadcast</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>POST</td><td><code>/telegram/notify</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>GET</td><td><code>/telegram/stats</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>GET, POST</td><td><code>/telegram/preferences</code></td><td><a href="./utilities-api/telegram.html">Telegram REST surface</a></td></tr><tr><td>POST</td><td><code>/whatsapp/notify</code></td><td><a href="./utilities-api/whatsapp.html">WhatsApp notification</a></td></tr></tbody></table><p>The Telegram resource contributes 11 method/path pairs. Its webhook acknowledges validated updates but does not yet dispatch them, and the REST broadcast handler currently returns zero delivery counts. Those limitations are documented on the Telegram page.</p><h2 id="websocket-protocol" tabindex="-1">WebSocket Protocol <a class="header-anchor" href="#websocket-protocol" aria-label="Permalink to &quot;WebSocket Protocol&quot;">​</a></h2><p>WebSocket streaming is not mounted below <code>/api/v1</code>. Clients connect to the proxy on port <code>8765</code>, authenticate, and send action messages.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Documentation</th></tr></thead><tbody><tr><td>LTP</td><td><a href="./websockets.html">LTP subscription</a></td></tr><tr><td>Quote</td><td><a href="./websockets.html">Quote subscription</a></td></tr><tr><td>Depth</td><td><a href="./websockets.html">Depth subscription</a></td></tr></tbody></table><p>Supported actions are <code>authenticate</code>, <code>subscribe</code>, <code>unsubscribe</code>, <code>unsubscribe_all</code>, <code>subscribe_orders</code>, <code>unsubscribe_orders</code>, <code>get_broker_info</code>, <code>get_supported_brokers</code>, and <code>ping</code>.</p><h2 id="order-constants" tabindex="-1">Order Constants <a class="header-anchor" href="#order-constants" aria-label="Permalink to &quot;Order Constants&quot;">​</a></h2><h3 id="exchanges" tabindex="-1">Exchanges <a class="header-anchor" href="#exchanges" aria-label="Permalink to &quot;Exchanges&quot;">​</a></h3><p><code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code>, <code>CDS</code>, <code>BCD</code>, <code>MCX</code>, <code>NCDEX</code>, <code>NCO</code>, <code>NSE_INDEX</code>, <code>BSE_INDEX</code>, <code>MCX_INDEX</code>, <code>GLOBAL_INDEX</code>, and <code>CRYPTO</code> are recognized by the shared validation constants. Broker capability metadata determines which subset is usable for the active broker.</p><h3 id="products-and-price-types" tabindex="-1">Products And Price Types <a class="header-anchor" href="#products-and-price-types" aria-label="Permalink to &quot;Products And Price Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kind</th><th>Values</th></tr></thead><tbody><tr><td>Product</td><td><code>MIS</code>, <code>CNC</code>, <code>NRML</code></td></tr><tr><td>Price type</td><td><code>MARKET</code>, <code>LIMIT</code>, <code>SL</code>, <code>SL-M</code></td></tr><tr><td>Action</td><td><code>BUY</code>, <code>SELL</code> (lowercase is normalized by order schemas)</td></tr></tbody></table><p>Regular order, smart-order, basket, split, and modify schemas accept numeric quantities. Fractional quantities are allowed only for <code>CRYPTO</code>; non-crypto quantities must be whole numbers. Options order quantities remain positive integers.</p><h2 id="response-and-status-conventions" tabindex="-1">Response And Status Conventions <a class="header-anchor" href="#response-and-status-conventions" aria-label="Permalink to &quot;Response And Status Conventions&quot;">​</a></h2><p>Most JSON resources return <code>status: &quot;success&quot;</code> or <code>status: &quot;error&quot;</code>, but broker payloads are normalized only at the wrapper level and some resources intentionally return CSV, plain text, or an empty webhook acknowledgement. Treat each endpoint page as authoritative for its payload.</p><p>Common status codes are:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>200</td><td>Request handled successfully</td></tr><tr><td>400</td><td>Invalid JSON, schema validation failure, unsupported mode, or invalid request state</td></tr><tr><td>401</td><td>Missing or invalid authentication on endpoints that use 401</td></tr><tr><td>403</td><td>Invalid API key or operation blocked by mode/policy</td></tr><tr><td>404</td><td>Broker module, symbol, order, or linked messaging user not found</td></tr><tr><td>429</td><td>Flask-Limiter rejected the request</td></tr><tr><td>500</td><td>Unhandled internal or broker error</td></tr></tbody></table><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><p>Defaults from <code>.sample.env</code> are <code>API_RATE_LIMIT=&quot;50 per second&quot;</code>, <code>ORDER_RATE_LIMIT=&quot;10 per second&quot;</code>, and <code>SMART_ORDER_RATE_LIMIT=&quot;10 per second&quot;</code>. Option Greeks, portfolio, SIP, Telegram, and WhatsApp resources each read their own variable, none of which appears in <code>.sample.env</code>, so their in-code fallbacks apply on a stock install. All values are deployment configuration and may contain compound semicolon-separated limits. See <a href="./rate-limiting.html">rate limiting</a>.</p><h2 id="client-libraries" tabindex="-1">Client Libraries <a class="header-anchor" href="#client-libraries" aria-label="Permalink to &quot;Client Libraries&quot;">​</a></h2><p>The Python client is available as <code>tradeboard</code> and is pinned by this application at <code>2.0.3</code>. Go and Node.js examples in <code>examples/</code> demonstrate direct REST integration; they are not declared here as separately versioned official SDK releases.</p>`,56)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
